-- =============================================================================
-- 517 — LE CAHIER D'EXERCICES DE 1RE (partie 5)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 517 --niveau 1re --fichiers anglais.n2,arts-plastiques.jumelles,biochimie-biologie.n1,biochimie-biologie.n2 --suffixe 5 > supabase/contenu/517_exercices_1re_5.sql
--
-- 78 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   anglais.n2              18 exercices · 6 chapitres
--   arts-plastiques.jumelles   9 exercices · 3 chapitres
--   biochimie-biologie.n1   27 exercices · 9 chapitres
--   biochimie-biologie.n2   24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('d76ec20f-5f2d-5124-851d-1418372353d7'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les vœux de Zoe la veille d’un contrôle","competence":"manier-langue","situation":"Zoe et Max s’échangent des messages la veille d’un contrôle de maths. Chacun regrette quelque chose.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Zoe","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"I wish I knew the answer to question 5!"},{"qui":"Max","texte":"I wish I had revised last night instead of playing games."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui exprime un regret sur le PASSÉ.","aide":"Pour un regret sur le passé, *wish* est suivi d’un temps composé.","type":"zone","document":"sms","multiple":true},{"enonce":"Après *I wish*, quel temps exprime un regret sur le PRÉSENT ?","aide":"Zoe ne connaît pas la réponse maintenant.","type":"choix","options":[{"id":"a","texte":"Le prétérit : I wish I knew"},{"id":"b","texte":"Le past perfect : I wish I had known"},{"id":"c","texte":"Le futur : I wish I will know"},{"id":"d","texte":"Le présent simple : I wish I know"}],"multiple":false},{"enonce":"Complète pour dire que tu ne parles pas espagnol.","aide":"C’est un regret sur le présent.","type":"trous","segments":["I wish I ",0," Spanish."],"banque":["spoke","will speak","had spoken","speak"]},{"enonce":"Relie chaque phrase française à sa traduction.","aide":"Repère d’abord les deux phrases qui parlent du passé.","type":"association","gauche":[{"id":"g0","texte":"J’aimerais savoir la réponse."},{"id":"g1","texte":"Je regrette de ne pas avoir travaillé."},{"id":"g2","texte":"Si seulement je l’avais écoutée !"},{"id":"g3","texte":"J’aurais dû écouter."}],"droite":[{"id":"d0","texte":"I wish I knew the answer."},{"id":"d1","texte":"If only I had listened to her!"},{"id":"d2","texte":"I should have listened."},{"id":"d3","texte":"I wish I had studied."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m13"]},"explication":"**had revised** : *wish* + past perfect exprime un regret sur le passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Le prétérit** : *I wish I knew* dit « j’aimerais savoir (mais je ne sais pas) »."},{"cle":{"type":"trous","trous":[["spoke"]]},"affichage":"spoke","explication":"**spoke** : prétérit « modal » après *wish*, pour un regret présent."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"*Wish* + prétérit : présent ; *wish* / *if only* + past perfect : passé ; *should have* + participe : reproche à soi-même."}]$ex$::jsonb),
  ('d76ec20f-5f2d-5124-851d-1418372353d7'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un courriel de regrets","competence":"comprendre-langue","situation":"Ben écrit à sa cousine Chloé un courriel plein de regrets. Aide-le à ranger ses phrases et à les réécrire.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Dear Chloé","blocs":["I wish I were closer to you: the distance is hard.","I wish I had come to your party last month. If only I had known!","And I wish you would answer my calls: you never pick up!"],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche la forme de *be* employée à la première personne dans l’anglais soutenu.","aide":"Cherche un mot qui n’est pas *was*.","type":"zone","document":"mail","multiple":false},{"enonce":"Range chaque phrase.","aide":"*Would* après *wish* vise le comportement d’un autre.","type":"categories","categories":[{"id":"c0","texte":"Regret présent"},{"id":"c1","texte":"Regret passé"},{"id":"c2","texte":"Agacement"}],"items":[{"id":"i0","texte":"I wish I lived closer to you."},{"id":"i1","texte":"I wish you would answer my calls."},{"id":"i2","texte":"I wish I had come to your party."},{"id":"i3","texte":"If only I had known!"}]},{"enonce":"Complète.","aide":"Après *I’d rather* + sujet, on emploie le prétérit.","type":"trous","segments":["I’d rather you ",0," tell anyone."],"banque":["didn’t","don’t","not","doesn’t"]},{"enonce":"Laquelle de ces phrases sur l’examen de demain est correcte ?","aide":"*Hope* parle du possible, *wish* de l’irréel.","type":"choix","options":[{"id":"a","texte":"I hope you pass your exam tomorrow."},{"id":"b","texte":"I hope you had passed your exam tomorrow."},{"id":"c","texte":"I wish you pass your exam tomorrow."},{"id":"d","texte":"I wish you will pass your exam tomorrow."}],"multiple":false},{"enonce":"Écris le regret de Ben : « Si seulement j’avais su ! ». Le premier mot est « If ».","aide":"*Wish* + sujet + past perfect.","type":"ordre","items":[{"id":"a","texte":"If"},{"id":"b","texte":"had"},{"id":"c","texte":"I"},{"id":"d","texte":"only"},{"id":"e","texte":"known"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**were** : dans l’anglais soutenu, on emploie *were* à toutes les personnes après *wish*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c1"}},"explication":"**Prétérit** : présent ; **past perfect** : passé ; ***wish* + sujet + *would*** : agacement."},{"cle":{"type":"trous","trous":[["didn t"]]},"affichage":"didn’t","explication":"**didn’t** : *I’d rather you didn’t tell anyone* (je préférerais que tu n’en parles à personne)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**I hope you pass your exam tomorrow.** : *hope* + présent, car l’examen est possible."},{"cle":{"type":"ordre","ids":["a","d","c","b","e"]},"explication":"**If only I had known** : *if only* + past perfect pour un regret passé."}]$ex$::jsonb),
  ('d76ec20f-5f2d-5124-851d-1418372353d7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Corriger le brouillon d’Ava","competence":"manier-langue","situation":"Ava prépare un message pour son frère Leo et son journal. Son brouillon contient trois erreurs sur *wish* et *it’s high time*.","documents":[{"id":"brouillon","type":"texte","genre":"lettre","titre":"Ava’s draft","blocs":["I wish I would have more time for sport.","It’s high time we leave for the station.","I’d rather you don’t tell anyone about the surprise.","I wish I had told her the truth."],"source":"Brouillon écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ava","emoji":"👧","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ava","texte":"I wish you would stop playing music at midnight!"},{"qui":"Leo","texte":"Sorry! If only I had known you were studying."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot fautif dans chacune des trois premières phrases.","aide":"Après *wish*, *it’s high time* et *I’d rather* + sujet, le verbe est au prétérit.","type":"zone","document":"brouillon","multiple":true},{"enonce":"Corrige la première phrase.","aide":"C’est un regret sur le présent : prétérit.","type":"trous","segments":["I wish I ",0," more time for sport."],"banque":["having","would have","have","had"]},{"enonce":"Que exprime la phrase d’Ava : « I wish you would stop playing music at midnight! » ?","aide":"*Wish* + sujet + *would* vise le comportement de quelqu’un d’autre.","type":"choix","options":[{"id":"a","texte":"Un regret sur le passé d’Ava"},{"id":"b","texte":"Un souhait possible à réaliser demain"},{"id":"c","texte":"Une règle de politesse"},{"id":"d","texte":"De l’agacement face au comportement de Leo"}],"multiple":false},{"enonce":"La réplique de Leo (« If only I had known… ») exprime…","aide":"Regarde le temps du verbe : *had known*.","type":"choix","options":[{"id":"a","texte":"Un regret sur le présent"},{"id":"b","texte":"Un regret sur le passé"},{"id":"c","texte":"Un ordre"},{"id":"d","texte":"Un souhait pour demain"}],"multiple":false},{"enonce":"Réécris la deuxième phrase du brouillon. Le premier mot est « It’s ».","aide":"*It’s high time* + sujet + prétérit.","type":"ordre","items":[{"id":"a","texte":"high"},{"id":"b","texte":"left"},{"id":"c","texte":"we"},{"id":"d","texte":"time"},{"id":"e","texte":"It’s"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m13","m20"]},"explication":"**would**, **leave** et **don’t** sont fautifs : il faut *had*, *left* et *didn’t*."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"**had** : *wish* + prétérit pour un regret présent."},{"cle":{"type":"choix","ids":["d"]},"explication":"**De l’agacement** : *wish* + *would* critique une habitude de l’autre."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Un regret sur le passé** : *if only* + past perfect."},{"cle":{"type":"ordre","ids":["e","a","d","c","b"]},"explication":"**It’s high time we left** : il est grand temps de partir."}]$ex$::jsonb),
  ('899fc82c-176a-51e2-92ea-e5f2c8b9eb4f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le règlement du club des jeunes","competence":"comprendre-langue","situation":"Dans le club de Naya, une affiche donne les règles. Lis-la attentivement : chaque phrase n’exprime pas la même chose.","documents":[{"id":"regles","type":"fiche","modele":"panneau","entete":"Youth Club Rules","emoji":"📋","lignes":[{"texte":"You have to sign in at the door.","id":"z1"},{"texte":"You are allowed to bring a snack.","id":"z2"},{"texte":"You mustn’t use your phone during activities.","id":"z3"},{"texte":"You don’t have to pay on Fridays.","id":"z4"}],"pied":"Thank you for respecting the rules.","teinte":"bleu","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la règle qui exprime une INTERDICTION.","aide":"*Mustn’t* exprime ce qu’il est interdit de faire.","type":"zone","document":"regles","multiple":false},{"enonce":"Touche la règle qui dit qu’il n’y a PAS d’obligation.","aide":"Les vendredis, on n’a pas besoin de payer.","type":"zone","document":"regles","multiple":false},{"enonce":"Quel équivalent de *can* utilise-t-on pour exprimer une permission ?","aide":"Regarde la règle sur le goûter.","type":"choix","options":[{"id":"a","texte":"be allowed to"},{"id":"b","texte":"be used to"},{"id":"c","texte":"be able to"},{"id":"d","texte":"be going to"}],"multiple":false},{"enonce":"Relie chaque phrase française à sa traduction.","aide":"Deux phrases ressemblent : l’une nie l’obligation, l’autre interdit.","type":"association","gauche":[{"id":"g0","texte":"Tu n’as pas besoin de venir."},{"id":"g1","texte":"Il est interdit de venir."},{"id":"g2","texte":"Elle pourra conduire."},{"id":"g3","texte":"J’ai dû partir tôt."}],"droite":[{"id":"d0","texte":"I had to leave early."},{"id":"d1","texte":"You mustn’t come."},{"id":"d2","texte":"You don’t have to come."},{"id":"d3","texte":"She will be able to drive."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**You mustn’t use your phone** : *mustn’t* = interdiction."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**You don’t have to pay** : *don’t have to* = absence d’obligation (ce n’est pas la peine)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**be allowed to** : *can* / *may* à la permission."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"*Don’t have to* : pas d’obligation ; *mustn’t* : interdiction ; *will be able to* : futur de *can* ; *had to* : passé de *must*."}]$ex$::jsonb),
  ('899fc82c-176a-51e2-92ea-e5f2c8b9eb4f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La traversée de Lena","competence":"comprendre-langue","situation":"Lena raconte une journée à la plage : ce qu’elle savait faire, ce qu’elle n’a pas pu faire, et ce qu’elle a réussi.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"A day at the beach","blocs":["As a child, Lena could swim very well.","Last Saturday, the sea was rough, but she managed to swim to the shore.","She wasn’t allowed to swim alone, so her uncle had to follow her in a boat."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’expression qui exprime une réussite ponctuelle, ce samedi-là.","aide":"On n’emploie pas *could* pour une réussite précise.","type":"zone","document":"recit","multiple":true},{"enonce":"Complète.","aide":"Il s’agit d’une réussite à un moment précis du passé.","type":"trous","segments":["The sea was rough, but she ",0," to swim to the shore."],"banque":["managed","must","could","can"]},{"enonce":"Range chaque phrase.","aide":"Observe la négation de *have to* et celle de *must*.","type":"categories","categories":[{"id":"c0","texte":"Obligation"},{"id":"c1","texte":"Interdiction"},{"id":"c2","texte":"Absence d’obligation"}],"items":[{"id":"i0","texte":"You must show your ticket."},{"id":"i1","texte":"You don’t have to wear a helmet."},{"id":"i2","texte":"You have to wear a helmet."},{"id":"i3","texte":"You mustn’t enter."}]},{"enonce":"Comment dit-on « Elle a dû suivre sa nièce » avec *have to* au passé ?","aide":"*Must* n’a pas de passé : on passe par *have to*.","type":"choix","options":[{"id":"a","texte":"She has to followed her niece."},{"id":"b","texte":"She must followed her niece."},{"id":"c","texte":"She had to follow her niece."},{"id":"d","texte":"She musted follow her niece."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m17"]},"explication":"**managed to** : une réussite ponctuelle (elle a réussi à nager jusqu’au rivage)."},{"cle":{"type":"trous","trous":[["managed"]]},"affichage":"managed","explication":"**managed** : *managed to* (ou *was able to*) pour une réussite ponctuelle."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c0","i3":"c1"}},"explication":"*Have to* / *must* : obligation ; *mustn’t* : interdiction ; *don’t have to* : absence d’obligation."},{"cle":{"type":"choix","ids":["c"]},"explication":"**She had to follow her niece.** : *had to* est le passé de *must*."}]$ex$::jsonb),
  ('899fc82c-176a-51e2-92ea-e5f2c8b9eb4f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le règlement du lycée d’échange","competence":"argumenter","situation":"Isla est en échange scolaire. Elle compare les règles de son ancien lycée à celles de son nouveau lycée avec son professeur.","documents":[{"id":"dialogue","type":"dialogue","modele":"sms","titre":"Chat with Mr Hale","participants":[{"nom":"Isla","emoji":"👧","cote":"gauche"},{"nom":"Mr Hale","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Isla","texte":"At my old school, we weren’t allowed to use our phones."},{"qui":"Mr Hale","texte":"Here, you may, but you have to switch them off in class. Next term, you will be able to join the club."}],"source":"Messages écrits pour l’exercice"},{"id":"tableau","type":"tableau","titre":"Two ways to oblige","colonnes":["Phrase","Who decides?"],"lignes":[["I must call my mum.","The speaker"],["I have to wear a uniform.","An outside rule"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’expression qui exprime l’absence de permission dans le passé.","aide":"Elle contient *allowed*.","type":"zone","document":"dialogue","multiple":true},{"enonce":"Touche l’expression qui exprime une obligation extérieure.","aide":"Elle est suivie de *switch them off*.","type":"zone","document":"dialogue","multiple":true},{"enonce":"Complète (capacité future : « il pourra »).","aide":"*Will can* est impossible : on emploie l’équivalent de *can* pour la capacité.","type":"trous","segments":["After the course, Jo will ",0," ",1," to swim 50 metres."],"banque":["able","be","allowed","can"]},{"enonce":"Range chaque phrase.","aide":"Relis le tableau.","type":"categories","categories":[{"id":"c0","texte":"Obligation venue de moi (must)"},{"id":"c1","texte":"Règle extérieure (have to)"}],"items":[{"id":"i0","texte":"You have to switch phones off in class."},{"id":"i1","texte":"I must remember to thank her."},{"id":"i2","texte":"I must call my mum."},{"id":"i3","texte":"I have to wear a uniform."}]},{"enonce":"Écris la phrase d’Isla. Le premier mot est « We ».","aide":"Sujet, *weren’t allowed to*, base verbale, puis le complément.","type":"ordre","items":[{"id":"a","texte":"to"},{"id":"b","texte":"phones"},{"id":"c","texte":"weren’t"},{"id":"d","texte":"use"},{"id":"e","texte":"allowed"},{"id":"f","texte":"We"},{"id":"g","texte":"our"}]}]}$ex$::jsonb,
