  ('21ec2fe9-9589-5820-ba90-7fd856cf3817'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Ce que veulent les parents de Noah","competence":"manier-langue","situation":"Noah écrit à une amie : ses parents ont des projets pour lui. Observe comment il dit « je veux que tu… » en anglais.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Noah","emoji":"👦","cote":"gauche"},{"nom":"Ella","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Noah","texte":"My parents want me to study law."},{"qui":"Ella","texte":"I’d like you to come to the cinema instead!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche, dans chaque phrase, le pronom complément placé entre le verbe et *to*.","aide":"Le pronom est à la forme complément : *me* et *you*.","type":"zone","document":"sms","multiple":true},{"enonce":"Écris : « Je veux que tu viennes ». Le premier mot est « I ».","aide":"Pas de *that* ni de subjonctif en anglais.","type":"ordre","items":[{"id":"a","texte":"come"},{"id":"b","texte":"you"},{"id":"c","texte":"to"},{"id":"d","texte":"I"},{"id":"e","texte":"want"}]},{"enonce":"Relie chaque phrase française à sa traduction.","aide":"Cherche la structure verbe + pronom + *to*.","type":"association","gauche":[{"id":"g0","texte":"J’aimerais qu’elle reste."},{"id":"g1","texte":"Il m’a demandé de l’aider."},{"id":"g2","texte":"Elle m’a dit d’attendre."},{"id":"g3","texte":"Ils attendent de nous que nous gagnions."}],"droite":[{"id":"d0","texte":"I’d like her to stay."},{"id":"d1","texte":"They expect us to win."},{"id":"d2","texte":"She told me to wait."},{"id":"d3","texte":"He asked me to help him."}]},{"enonce":"Laquelle est correcte ?","aide":"Le pronom est complément, et il n’y a pas de *that*.","type":"choix","options":[{"id":"a","texte":"I want he to leave."},{"id":"b","texte":"I want he leaves."},{"id":"c","texte":"I want him to leave."},{"id":"d","texte":"I want that he leaves."}],"multiple":false}]}$ex$::jsonb,
