ine au-delà du seuil ?","aide":"Les transporteurs sont en nombre limité.","type":"choix","options":[{"id":"a","texte":"Les tubes sécrètent du glucose vers l’urine"},{"id":"b","texte":"Les transporteurs de réabsorption sont saturés"},{"id":"c","texte":"L’ADH détruit le glucose dans le tube collecteur"},{"id":"d","texte":"Les podocytes laissent passer plus de glucose"}],"multiple":false}]}$ex$::jsonb,
