   $ex${"titre":"Transporter ou recevoir : P1 et P2","competence":"analyser-document","situation":"Une équipe étudie deux protéines membranaires, P1 et P2, de cellules de foie. Elle ajoute du glucose ou de l’insuline marqués dans le milieu extérieur et mesure la radioactivité à l’intérieur des cellules.","documents":[{"id":"mesures","type":"tableau","titre":"Résultats de l’expérience","colonnes":["Condition","Radioactivité à l’intérieur (u.a.)","Réponse de la cellule"],"lignes":[["Glucose marqué, P1 fonctionnelle",80,"—"],["Glucose marqué, P1 bloquée",4,"—"],["Insuline marquée, P2 fonctionnelle",0,"stockage du glucose activé"],["Insuline marquée, P2 bloquée",0,"aucune"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"},{"id":"schema","type":"schema","titre":"Les deux protéines dans la membrane","largeur":320,"hauteur":180,"elements":[{"forme":"rect","x":20,"y":70,"l":280,"h":40,"teinte":"brun","motif":"hachures"},{"forme":"ellipse","cx":100,"cy":90,"rx":20,"ry":40,"teinte":"turquoise","motif":"plein","id":"z1","zone":true},{"forme":"ellipse","cx":220,"cy":85,"rx":20,"ry":32,"teinte":"turquoise","motif":"plein","id":"z2","zone":true},{"forme":"texte","x":100,"y":150,"texte":"P1","gras":true,"taille":"grand"},{"forme":"texte","x":220,"y":150,"texte":"P2","gras":true,"taille":"grand"},{"forme":"texte","x":160,"y":20,"texte":"Face extérieure","taille":"petit","italique":true},{"forme":"texte","x":160,"y":172,"texte":"Face intérieure","taille":"petit","italique":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"D’après le tableau, touche la protéine qui fait passer le glucose à l’intérieur de la cellule.","aide":"Compare la radioactivité intérieure avec P1 fonctionnelle puis bloquée.","type":"zone","document":"schema","multiple":false},{"enonce":"Par quel facteur la radioactivité intérieure est-elle multipliée quand P1 fonctionne ?","aide":"Divise la valeur obtenue avec P1 fonctionnelle par celle avec P1 bloquée.","type":"nombre"},{"enonce":"L’insuline marquée n’entre jamais, pourtant la cellule réagit quand P2 fonctionne. Que fait P2 ?","aide":"Regarde la radioactivité intérieure et la réponse de la cellule pour l’insuline.","type":"choix","options":[{"id":"a","texte":"Elle fait entrer l’insuline puis la détruit dans la cellule"},{"id":"b","texte":"Elle transporte le glucose en même temps que l’insuline entre"},{"id":"c","texte":"Elle fixe l’insuline sans la faire entrer et déclenche une réponse"},{"id":"d","texte":"Elle empêche l’insuline de se fixer sur la membrane de la cellule"}],"multiple":false},{"enonce":"Classe ces protéines membranaires.","aide":"Un transporteur fait passer une molécule ; un récepteur fixe un messager.","type":"categories","categories":[{"id":"c0","texte":"Transporteur"},{"id":"c1","texte":"Récepteur"}],"items":[{"id":"i0","texte":"Récepteur de l’insuline"},{"id":"i1","texte":"Transporteur du glucose"},{"id":"i2","texte":"Aquaporine"}]}]}$ex$::jsonb,
