   $ex${"titre":"Quelle température pour ouvrir ce fragment ?","competence":"analyser-document","situation":"Lina analyse un fragment d’ADN double brin inconnu. Elle dose ses bases, puis cherche à quelle température ses deux brins se séparent grâce à une courbe d’étalonnage.","documents":[{"id":"dosage","type":"tableau","titre":"Dosage des bases du fragment","colonnes":["Base","Part des bases"],"lignes":[["Adénine","20 %"],["Thymine","?"],["Guanine","?"],["Cytosine","?"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"},{"id":"etalon","type":"graphique","forme":"courbe","titre":"Courbe d’étalonnage","categories":["30 %","40 %","50 %","60 %","70 %"],"series":[{"nom":"Température de dénaturation","valeurs":[82,86,90,94,98],"teinte":"corail"}],"axeY":{"titre":"Température de dénaturation","unite":"°C","min":70,"max":100,"pas":5},"axeX":{"titre":"Part de bases G + C"},"valeurs":false,"source":"Valeurs arrondies, écrites pour l’exercice"}],"questions":[{"enonce":"Touche le point du fragment le plus riche en G + C.","aide":"Cherche l’abscisse la plus élevée.","type":"zone","document":"etalon","multiple":false},{"enonce":"Quelle est la part de thymine du fragment dosé ?","aide":"Dans l’ADN double brin, l’adénine s’apparie avec la thymine.","type":"nombre","unite":"%"},{"enonce":"Quelle est la part de bases G + C du fragment dosé ?","aide":"Retire A et T du total (100 %).","type":"nombre","unite":"%"},{"enonce":"À quelle température les deux brins de ce fragment se séparent-ils ?","aide":"Lis la courbe pour la part de G + C que tu viens de trouver.","type":"nombre","unite":"°C"},{"enonce":"Pourquoi un fragment riche en G + C résiste-t-il mieux à la chaleur ?","aide":"Plus il y a de liaisons à rompre, plus il faut chauffer.","type":"choix","options":[{"id":"a","texte":"Les paires G–C contiennent un sucre différent des paires A–T"},{"id":"b","texte":"Les paires G–C sont reliées par des liaisons phosphodiester solides"},{"id":"c","texte":"Chaque paire G–C compte