   $ex${"titre":"Quelle taille ont vraiment ces objets ?","competence":"calculer","situation":"Un technicien de laboratoire mesure trois objets sur des clichés de microscopie. Il connaît le grossissement de chaque cliché et doit retrouver les tailles réelles.","documents":[{"id":"cliches","type":"tableau","titre":"Mesures sur les clichés","colonnes":["Objet observé","Grossissement","Taille sur le cliché"],"lignes":[["Cellule d’épithélium","× 400","12 mm"],["Bactérie","× 2 000","8 mm"],["Virus","× 200 000","24 mm"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche le grossissement le plus élevé du tableau.","aide":"Compare les trois grossissements.","type":"zone","document":"cliches","multiple":false},{"enonce":"Quelle est la taille réelle de la cellule d’épithélium, en micromètres ?","aide":"Divise 12 mm par 400, puis convertis (1 mm = 1 000 µm).","type":"nombre","unite":"µm"},{"enonce":"Quelle est la taille réelle du virus, en nanomètres ?","aide":"Divise 24 mm par 200 000, puis convertis : 1 mm = 1 000 000 nm.","type":"nombre","unite":"nm"},{"enonce":"Range ces objets du plus petit au plus grand (la bactérie mesure 4 µm).","aide":"Compare 120 nm, 4 µm et 30 µm.","type":"ordre","items":[{"id":"a","texte":"Virus"},{"id":"b","texte":"Cellule d’épithélium"},{"id":"c","texte":"Bactérie"}]},{"enonce":"Le microscope optique ne distingue pas deux points distants de moins de 0,2 µm. Que faut-il utiliser pour observer le virus ?","aide":"Compare la taille du virus à la limite de 0,2 µm.","type":"choix","options":[{"id":"a","texte":"Un microscope électronique"},{"id":"b","texte":"Un microscope optique avec un grossissement plus fort"},{"id":"c","texte":"Une loupe binoculaire"},{"id":"d","texte":"Une échographie"}],"multiple":false}]}$ex$::jsonb,
