   $ex${"titre":"Quelle imagerie pour quel patient ?","competence":"analyser-document","situation":"À l’hôpital, quatre patients attendent un examen. L’infirmière consulte la fiche des techniques d’imagerie et la liste des questions posées par les médecins.","documents":[{"id":"techniques","type":"tableau","titre":"Les techniques d’imagerie","colonnes":["Technique","Principe","Ce qu’on voit bien","Rayonnement ionisant"],"lignes":[["Radiographie","rayons X absorbés par les tissus denses","os","oui"],["Échographie","ultrasons réfléchis aux interfaces","tissus mous","non"],["Radiographie avec produit de contraste","substance opaque aux rayons X avalée ou injectée","tube digestif, vaisseaux","oui"]],"enteteLignes":true,"source":"Texte écrit pour l’exercice"},{"id":"patients","type":"tableau","titre":"Les patients du jour","colonnes":["Patient","Situation","Question du médecin"],"lignes":[["Théo","15 ans, chute de vélo","Le poignet est-il fracturé ?"],["Salma","28 ans, enceinte de 20 semaines","Le fœtus se développe-t-il normalement ?"],["M. Roche","60 ans, douleur dans le flanc","Le rein présente-t-il une anomalie ?"],["Mme Diallo","45 ans, douleurs digestives","Le tube digestif est-il rétréci ?"]],"enteteLignes":true,"source":"Situations écrites pour l’exercice"}],"questions":[{"enonce":"Classe chaque patient selon l’examen le plus adapté.","aide":"Os : rayons X ; tissus mous : ultrasons ; tube digestif : il faut le rendre opaque.","type":"categories","categories":[{"id":"c0","texte":"Radiographie"},{"id":"c1","texte":"Échographie"},{"id":"c2","texte":"Radiographie avec produit de contraste"}],"items":[{"id":"i0","texte":"Salma"},{"id":"i1","texte":"Mme Diallo"},{"id":"i2","texte":"M. Roche"},{"id":"i3","texte":"Théo"}]},{"enonce":"Touche la case qui indique ce que la radiographie simple montre bien.","aide":"Les tissus denses absorbent les rayons X.","type":"zone","document":"techniques","multiple":false},{"enonce":"Pourquoi choisit-on l’échographie plutôt que la radiographie pour le suivi de la grossesse de Salma ?","aide":"Regarde les deux dernières colonnes de la ligne « Échographie ».","type":"choix","options":[{"id":"a","texte":"Les ultrasons sont absorbés par les os comme les rayons X"},{"id":"b","texte":"Les rayons X ne traversent jamais les tissus mous du fœtus"},{"id":"c","texte":"Les ultrasons ne sont pas ionisants et montrent bien les tissus mous"},{"id":"d","texte":"L’échographie permet d’observer les cellules une à une"}],"multiple":false},{"enonce":"Pourquoi une radiographie simple conviendrait-elle mal pour examiner le rein de M. Roche ?","aide":"La radiographie montre bien ce qui est dense.","type":"choix","options":[{"id":"a","texte":"Les os du rein empêchent la lecture de l’image"},{"id":"b","texte":"Le rein émet lui-même un rayonnement ionisant"},{"id":"c","texte":"Les tissus mous sont peu contrastés aux rayons X"},{"id":"d","texte":"Le rein est trop dense pour laisser passer les ultrasons"}],"multiple":false}]}$ex$::jsonb,
